    { uint64_t bits = 0; memcpy( &bits, &value.scale, 8 ); table_cook_put( at + 56, bits, 8, order ); }
    table_cook_put( at + 64, (uint64_t) value.flags, 8, order );
    table_cook_put( at + 72, (uint64_t) value.static_prop_id, 4, order );
